"""Generate zz_kernel_tables.go: the tables of the float64 exp/log kernels
(kernels.go).

    uv run --with mpmath==1.4.1 python testdata/gen/kernel_tables.py

expT[j] = 2^(j/128) as a double-double, j = 0..127.
logT[j-192] = {invc, logc_hi, logc_lo}, j = 192..384: invc = 256/j rounded
to float64, and -log(invc) — computed from that
float64 value itself, so log(m) = -log(invc) + log1p(m*invc - 1) holds
exactly — split as logc_hi, a multiple of 2^-42 (so k*ln2Hi42 + logc_hi is
exact for |k| < 2^10), and logc_lo, the rest to 2^-96.
ln2/128 split for the Cody-Waite reduction: expC1 has 35 significant bits
(k*expC1 exact for |k| < 2^18), expC1 + expC2 = ln2/128 to about 2^-88
relative; ln2 split with ln2Hi42 a multiple of 2^-42 (42 bits, k*ln2Hi42
exact for |k| < 2^11).
"""

import os
import subprocess

from mpmath import mp, mpf, log, ldexp, floor, nint

mp.prec = 400


def split(v):
    hi = float(v)
    lo = float(v - mpf(hi))
    return hi, lo


def trunc_bits(v, bits):
    # v rounded to nearest with `bits` significant bits
    e = int(floor(log(abs(v), 2)))
    s = ldexp(1, bits - 1 - e)
    return float(nint(v * s) / s)


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    out = os.path.normpath(os.path.join(here, "..", "..", "zz_kernel_tables.go"))
    L = []
    w = L.append
    w("// Code generated by testdata/gen/kernel_tables.py (mpmath 1.4.1, 400 bits); DO NOT EDIT.")
    w("")
    w("package special")
    w("")
    ln2 = log(2)
    c = ln2 / 128
    c1 = trunc_bits(c, 35)
    c2 = float(c - mpf(c1))
    l1 = trunc_bits(ln2, 42)
    l2 = float(ln2 - mpf(l1))
    w("const (")
    w("\texpInvLn2N = %r // 128/ln2" % float(128 / ln2))
    w("\texpC1      = %r // ln2/128, 35 bits" % c1)
    w("\texpC2      = %r // ln2/128 - expC1" % c2)
    w("\tln2Hi42    = %r // ln2, 42 bits" % l1)
    w("\tln2Lo42    = %r // ln2 - ln2Hi42" % l2)
    w(")")
    w("")
    w("// expT[j] = 2^(j/128) as {hi, lo}.")
    w("var expT = [128][2]float64{")
    for j in range(128):
        h, l = split(mpf(2) ** (mpf(j) / 128))
        w("\t{%r, %r}," % (h, l))
    w("}")
    w("")
    w("// logT[j-192] = {invc = RN(256/j), -log(invc) to a multiple of 2^-42, the rest}, j = 192..384.")
    w("var logT = [193][3]float64{")
    for j in range(192, 385):
        inv = float(mpf(256) / j)
        v = -log(mpf(inv))
        h = float(nint(v * mpf(2) ** 42) / mpf(2) ** 42)
        l = float(v - mpf(h))
        w("\t{%r, %r, %r}," % (inv, h, l))
    w("}")
    with open(out, "w") as f:
        f.write("\n".join(L) + "\n")
    subprocess.run(["gofmt", "-w", out], check=True)


if __name__ == "__main__":
    main()
